function draw(t){
  ctx.clearRect(0, 0, W, H);
  pts.forEach(p => {
    const a = t * 2 * Math.PI / 1.8 + p.seed;
    ctx.beginPath(); ctx.arc(p.x + Math.cos(a) * 2, p.y + Math.sin(a) * 2, 2, 0, 6.283); ctx.fill();
