} });

const cells = gsap.utils.toArray('.cell');
const tl = gsap.timeline({ paused: true });
cells.forEach((cell, i) => {
  if ((i * 37 % 100) < 15) tl.fromTo(cell, { opacity: 0 },
    { opacity: 0.3, duration: 0.5, repeat: 1, yoyo: true, ease: 'sine.inOut' }, (i % 10) * 0.1);
});

const phase = { value: 0 };
const tl = gsap.timeline({ paused: true });
tl.to(phase, { value: Math.PI * 2, duration: 6, ease: 'none', repeat: -1, onUpdate: () => {
  ctx.clearRect(0, 0, 1920, 1080);
  for (let j=0; j<12; j++) { ctx.beginPath();
    for (let x=0; x<=1920; x+=8) { const y=300+j*36+30*Math.sin(x/240*Math.PI*2+phase.value+j*.3); x===0?ctx.moveTo(x,y):ctx.lineTo(x,y); }
    ctx.stroke();
  }
} });

.fx { display:grid; grid-template-columns:repeat(2,24px); perspective:140px; }
